"""Professional UI for GLPI Builder.

All mutations remain on authenticated, CSRF-protected Flask routes. A tiny
first-party script only refreshes status text and controls confirmation dialogs.
"""

APP_SHELL = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{{ page_title }} · GLPI Builder</title>
<style>
:root{color-scheme:light;--bg:#f5f7fb;--surface:#fff;--soft:#f8fafc;--line:#dce4ee;--ink:#172033;--muted:#64748b;--navy:#12233f;--blue:#2364d2;--blue2:#184da8;--green:#16845b;--amber:#a16207;--red:#b42318;--shadow:0 10px 32px #16345f0c}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}button,input,select{font:inherit}
.app{min-height:100vh;display:grid;grid-template-columns:244px minmax(0,1fr)}.sidebar{position:sticky;top:0;height:100vh;display:flex;flex-direction:column;padding:22px 15px;background:linear-gradient(180deg,#12233f,#172e50);color:#dce7f6}.brand{display:flex;align-items:center;gap:11px;padding:0 9px 24px}.brand-mark{display:grid;place-items:center;width:38px;height:38px;border-radius:11px;background:linear-gradient(145deg,#3d7ce3,#1b55b4);box-shadow:0 8px 22px #07172e70;color:#fff;font-size:18px;font-weight:800}.brand strong{display:block;color:#fff;font-size:15px}.brand span{display:block;color:#9fb1c9;font-size:11px}.nav-label{padding:10px 12px 7px;color:#7f94af;font-size:10px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.nav{display:grid;gap:4px}.nav a{display:flex;align-items:center;gap:11px;padding:10px 12px;border-radius:9px;color:#bfcde0;font-weight:650}.nav a:hover{background:#ffffff0c;color:#fff;text-decoration:none}.nav a.active{background:#ffffff16;color:#fff;box-shadow:inset 3px 0 #67a0ff}.nav-icon{width:20px;text-align:center;color:#8fb2e9}.sidebar-foot{margin-top:auto;padding:16px 10px 2px;border-top:1px solid #ffffff14;color:#8fa2bc;font-size:11px}.sidebar-foot strong{display:block;color:#c8d5e6;font-size:12px}
.workspace{min-width:0}.topbar{height:68px;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:0 30px;border-bottom:1px solid var(--line);background:#ffffffde;backdrop-filter:blur(12px);position:sticky;top:0;z-index:9}.crumb{color:var(--muted);font-size:12px}.crumb strong{color:#334155}.top-actions{display:flex;align-items:center;gap:10px}.version,.preview-label{padding:5px 9px;border-radius:999px;background:#edf4ff;color:#315c9f;font-size:11px;font-weight:750}.preview-label{background:#fff3d9;color:#805000}.signout{margin:0}.signout button,.exit-preview{padding:7px 10px;border:1px solid var(--line);border-radius:8px;background:#fff;color:#475569;box-shadow:none}.exit-preview{font-weight:700}
.content{max-width:1320px;margin:auto;padding:30px}.page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:24px}.page-head h1{margin:0;color:var(--navy);font-size:27px;letter-spacing:-.03em}.page-head p{margin:5px 0 0;color:var(--muted)}.head-actions{display:flex;gap:9px;flex-wrap:wrap}
.card{min-width:0;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:20px;box-shadow:var(--shadow)}.card h2,.card h3{margin:0;color:var(--navy)}.card h2{font-size:18px}.card h3{font-size:15px}.card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;margin-bottom:16px}.card-head p{margin:4px 0 0;color:var(--muted);font-size:12px}.grid{display:grid;gap:16px}.grid>*{min-width:0}.stats{grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:20px}.stat{padding:18px}.stat-label{color:var(--muted);font-size:12px;font-weight:650}.stat-value{margin:7px 0 2px;color:var(--navy);font-size:28px;font-weight:800;letter-spacing:-.04em}.stat-detail{color:var(--muted);font-size:11px}.two-col{grid-template-columns:minmax(0,1.55fr) minmax(300px,.8fr)}.project-grid{grid-template-columns:repeat(auto-fit,minmax(320px,1fr))}
.button,button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:39px;padding:8px 13px;border:0;border-radius:9px;background:linear-gradient(180deg,var(--blue),var(--blue2));box-shadow:0 6px 16px #205fc326;color:#fff;font-weight:750;cursor:pointer;text-decoration:none}.button:hover{text-decoration:none;filter:brightness(1.04)}.button.secondary,button.secondary{border:1px solid var(--line);background:#fff;box-shadow:none;color:#405069}.button.ghost,button.ghost{background:#eef3f8;box-shadow:none;color:#405069}.button.danger,button.danger{background:var(--red)}.button.small,button.small{min-height:32px;padding:6px 10px;font-size:12px}
.notice{display:flex;gap:10px;margin-bottom:14px;padding:12px 14px;border:1px solid #bcd4f6;border-radius:10px;background:#eff6ff;color:#274b7c}.notice.ok{border-color:#a7dbc4;background:#effaf5;color:#176542}.notice.err{border-color:#f1b8b2;background:#fff3f2;color:#8d231b}.notice.warning{border-color:#eed09b;background:#fff8e8;color:#805000}
.status{display:inline-flex;align-items:center;gap:6px;padding:4px 9px;border-radius:999px;background:#eef2f6;color:#536176;font-size:11px;font-weight:750}.status:before{content:"";width:6px;height:6px;border-radius:50%;background:#9aa7b8}.status.running,.status.ready{background:#e9f8f0;color:#176542}.status.running:before,.status.ready:before{background:#27a366}.status.warning{background:#fff3d9;color:#805000}.status.warning:before{background:#d69319}.status.failed{background:#fff0ef;color:#8d231b}.status.failed:before{background:#d94a3f}
.project-card{display:flex;flex-direction:column;gap:15px}.project-title{display:flex;justify-content:space-between;gap:12px}.project-title h3{font-size:17px}.status-row{display:flex;gap:6px;flex-wrap:wrap}.meta-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.meta-item span{display:block;color:var(--muted);font-size:11px}.meta-item strong{display:block;margin-top:2px;color:#334155;overflow-wrap:anywhere}.card-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:auto;padding-top:14px;border-top:1px solid #edf1f5}
.issue-list,.activity-list{list-style:none;margin:0;padding:0}.issue-list li,.activity-list li{padding:12px 0;border-bottom:1px solid #edf1f5}.issue-list li:last-child,.activity-list li:last-child{border-bottom:0}.issue-title{font-weight:700}.issue-detail,.activity-meta{color:var(--muted);font-size:12px}.empty{padding:34px 18px;text-align:center;color:var(--muted)}.empty strong{display:block;margin-bottom:4px;color:#405069}
.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:11px}table{width:100%;border-collapse:collapse}th,td{padding:12px 14px;border-bottom:1px solid #edf1f5;text-align:left;vertical-align:top}th{background:#f8fafc;color:#64748b;font-size:10px;letter-spacing:.08em;text-transform:uppercase}tr:last-child td{border-bottom:0}td small{display:block;color:var(--muted)}code{padding:2px 5px;border-radius:5px;background:#f0f3f7;color:#334155;font-size:12px}
.tabs{display:flex;gap:4px;margin:0 0 18px;padding:4px;border:1px solid var(--line);border-radius:11px;background:#f2f5f9;width:max-content;max-width:100%;overflow:auto}.tabs a{padding:7px 11px;border-radius:7px;color:#5b687b;font-weight:700;white-space:nowrap}.tabs a.active{background:#fff;box-shadow:0 2px 7px #15345b16;color:var(--blue)}.detail-layout{grid-template-columns:minmax(0,1.45fr) minmax(280px,.7fr)}.stack{display:grid;gap:16px}.definition{display:grid;grid-template-columns:minmax(145px,.85fr) minmax(0,1.15fr);column-gap:24px;margin:0}.definition dt,.definition dd{margin:0;padding:10px 0;border-bottom:1px solid #edf1f5}.definition dt{color:var(--muted);overflow-wrap:anywhere}.definition dd{font-weight:650;overflow-wrap:anywhere}
label{display:block;margin:13px 0 6px;color:#334155;font-size:12px;font-weight:750}input,select{width:100%;min-height:42px;padding:8px 11px;border:1px solid #cbd5e1;border-radius:9px;background:#fff;color:var(--ink);outline:none}input:focus,select:focus{border-color:var(--blue);box-shadow:0 0 0 3px #2364d21c}.field-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.check{display:flex;align-items:flex-start;gap:8px;font-weight:550}.check input{width:auto;min-height:auto;margin-top:3px}.form-actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:18px}.help{margin-top:6px;color:var(--muted);font-size:11px}.danger-zone{border-color:#f0c2bd;background:#fffafa}details{border-top:1px solid #edf1f5;margin-top:14px;padding-top:12px}summary{cursor:pointer;color:#3f4e63;font-weight:750}
.wizard{grid-template-columns:minmax(0,1.45fr) 340px;align-items:start}.steps{display:flex;gap:0;margin-bottom:22px}.step-marker{display:flex;align-items:center;flex:1;color:#8793a5;font-size:11px;font-weight:750}.step-marker:after{content:"";height:1px;flex:1;margin:0 9px;background:#dce3ec}.step-marker:last-child:after{display:none}.step-number{display:grid;place-items:center;width:25px;height:25px;margin-right:7px;border-radius:50%;background:#e8edf4;color:#607087}.step-marker.active{color:var(--blue)}.step-marker.active .step-number{background:var(--blue);color:#fff}.mode-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.mode{position:relative;display:flex;gap:10px;margin:0;padding:14px;border:1px solid #cbd5e1;border-radius:11px;background:#fff;font-weight:550}.mode:has(input:checked){border-color:#7aa5eb;background:#f4f8ff;box-shadow:0 0 0 2px #2364d212}.mode input{width:auto;min-height:auto}.mode strong{display:block}.mode span span{display:block;margin-top:3px;color:var(--muted);font-size:11px}.wizard-summary{position:sticky;top:88px}.summary-row{display:flex;justify-content:space-between;gap:20px;padding:10px 0;border-bottom:1px solid #edf1f5}.summary-row span{color:var(--muted)}.summary-row strong{text-align:right}.restore-fields{display:block}.mode-grid:has(input[value=fresh]:checked)~.restore-fields{display:none}
.security-banner{display:flex;gap:12px;padding:15px;border:1px solid #efd29f;border-radius:11px;background:#fff9ec}.security-banner strong{display:block;color:#78500b}.security-banner p{margin:3px 0 0;color:#8a672c;font-size:12px}.settings-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.audit-icon{display:grid;place-items:center;width:32px;height:32px;border-radius:9px;background:#edf4ff;color:var(--blue);font-weight:800}.activity-row{display:grid;grid-template-columns:32px minmax(0,1fr) auto;gap:12px;align-items:start}.activity-name{font-weight:700}.activity-time{color:var(--muted);font-size:11px;white-space:nowrap}
.mobile-nav{display:none}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.code-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:14px}.code-view{max-width:100%;max-height:70vh;margin:0;padding:18px;border:1px solid #263b57;border-radius:11px;background:#12233f;color:#dce7f6;overflow:auto;font:12px/1.6 ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;tab-size:2;white-space:pre}.notice .code-view{white-space:pre-wrap;overflow-wrap:anywhere}.code-note{color:var(--muted);font-size:12px}.simulated-project form:not(.demo-schedule-form) button{opacity:.48;pointer-events:none;box-shadow:none}.simulated-project form:not(.demo-schedule-form) input,.simulated-project form:not(.demo-schedule-form) select{background:#f5f7fa;color:#64748b}
.refresh-group{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:11px}.icon-button{min-height:31px;padding:5px 9px;border:1px solid var(--line);background:#fff;box-shadow:none;color:#405069;font-size:11px}.error-summary{display:grid;gap:5px}.error-summary>strong{font-size:14px}.error-summary span{display:block}.error-summary details{border-color:#efc2bd}.policy-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.policy-item{padding:12px;border:1px solid var(--line);border-radius:10px;background:var(--soft)}.policy-item strong{display:block}.policy-item span{color:var(--muted);font-size:11px}.advanced-zone{border-color:#efc2bd;background:#fffafa}.confirmation-trigger{border:1px solid #e5aaa3;background:#fff;color:var(--red);box-shadow:none}dialog{width:min(520px,calc(100% - 28px));padding:0;border:1px solid var(--line);border-radius:16px;box-shadow:0 24px 80px #12233f4a;color:var(--ink)}dialog::backdrop{background:#12233f99;backdrop-filter:blur(2px)}.dialog-body{padding:22px}.dialog-body h2{margin:0 0 7px}.dialog-body p{color:var(--muted)}.dialog-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.backup-meta{display:flex;gap:7px;flex-wrap:wrap;margin-top:4px}.compat-list{margin:0;padding-left:18px;color:var(--muted)}.compat-list li{margin:5px 0}
@media(max-width:1050px){.stats{grid-template-columns:repeat(2,1fr)}.two-col,.detail-layout,.wizard{grid-template-columns:1fr}.wizard-summary{position:static}.settings-grid{grid-template-columns:1fr}}
@media(max-width:760px){.app{display:block}.sidebar{display:none}.topbar{height:60px;padding:0 16px}.content{padding:20px 14px 82px}.page-head{align-items:flex-start;flex-direction:column}.mobile-nav{position:fixed;display:grid;grid-template-columns:repeat(5,1fr);left:0;right:0;bottom:0;z-index:12;border-top:1px solid var(--line);background:#fff;padding:7px 4px max(7px,env(safe-area-inset-bottom))}.mobile-nav a{display:grid;place-items:center;gap:2px;color:#708096;font-size:9px;font-weight:700}.mobile-nav a.active{color:var(--blue)}.mobile-nav span{font-size:16px}.field-row,.mode-grid,.policy-list{grid-template-columns:1fr}.definition{grid-template-columns:1fr}.definition dt{padding-bottom:0;border:0}.definition dd{padding-top:3px}.top-actions .version,.refresh-group span{display:none}.dialog-actions{flex-direction:column-reverse}.dialog-actions button{width:100%}}
@media(max-width:520px){.stats{grid-template-columns:1fr 1fr;gap:10px}.stat{padding:14px}.stat-value{font-size:23px}.project-grid{grid-template-columns:1fr}.meta-grid{grid-template-columns:1fr}.content{padding-left:10px;padding-right:10px}.card{padding:16px}}
</style></head><body>
<div class="app"><aside class="sidebar"><div class="brand"><div class="brand-mark">G</div><div><strong>GLPI Builder</strong><span>Deployment console</span></div></div>
<div class="nav-label">Workspace</div><nav class="nav" aria-label="Primary">
<a class="{{ 'active' if active_page=='overview' }}" href="{{ url_for('index') }}"><span class="nav-icon">⌂</span>Overview</a>
<a class="{{ 'active' if active_page=='projects' }}" href="{{ url_for('projects_page') }}"><span class="nav-icon">▦</span>Projects</a>
<a class="{{ 'active' if active_page=='backups' }}" href="{{ url_for('backups_page') }}"><span class="nav-icon">◫</span>Backups</a>
<a class="{{ 'active' if active_page=='activity' }}" href="{{ url_for('activity_page') }}"><span class="nav-icon">≡</span>Activity</a>
<a class="{{ 'active' if active_page=='settings' }}" href="{{ url_for('settings_page') }}"><span class="nav-icon">⚙</span>Settings</a></nav>
<div class="sidebar-foot"><strong>Authenticated console</strong>Administrative actions are protected by CSRF and a single-operation lock.</div></aside>
<section class="workspace"><header class="topbar"><div class="crumb">GLPI Builder / <strong>{{ page_title }}</strong></div><div class="top-actions"><div class="refresh-group"><span data-last-checked>Last checked on load</span><button class="icon-button" type="button" data-refresh-status>Refresh</button></div>{% if test_preview_active %}<span class="preview-label">Read-only preview</span><a class="exit-preview" href="{{ url_for('test_preview_exit') }}">Exit preview</a>{% else %}<span class="version">{{ app_version }}</span><form class="signout" method="post" action="{{ url_for('logout') }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><button type="submit">Sign out</button></form>{% endif %}</div></header>
<main class="content">{% with messages=get_flashed_messages(with_categories=true) %}{% for category,message in messages %}<div class="notice {{ category }}" role="status">{{ message|safe }}</div>{% endfor %}{% endwith %}
__PAGE_CONTENT__
</main></section></div>
<nav class="mobile-nav" aria-label="Mobile navigation"><a class="{{ 'active' if active_page=='overview' }}" href="{{ url_for('index') }}"><span>⌂</span>Overview</a><a class="{{ 'active' if active_page=='projects' }}" href="{{ url_for('projects_page') }}"><span>▦</span>Projects</a><a class="{{ 'active' if active_page=='backups' }}" href="{{ url_for('backups_page') }}"><span>◫</span>Backups</a><a class="{{ 'active' if active_page=='activity' }}" href="{{ url_for('activity_page') }}"><span>≡</span>Activity</a><a class="{{ 'active' if active_page=='settings' }}" href="{{ url_for('settings_page') }}"><span>⚙</span>Settings</a></nav>
<script src="{{ url_for('ui_javascript') }}" defer></script></body></html>"""

OVERVIEW = r"""
<div class="page-head"><div><h1>Infrastructure overview</h1><p>Health, backups and recent activity across every managed GLPI environment.</p></div><div class="head-actions"><a class="button secondary" href="{{ url_for('backups_page') }}">Review backups</a><a class="button" href="{{ url_for('new_project_page') }}">New project</a></div></div>
<section class="grid stats"><article class="card stat"><div class="stat-label">Managed projects</div><div class="stat-value">{{ stats.projects }}</div><div class="stat-detail">{{ stats.running }} fully operational</div></article><article class="card stat"><div class="stat-label">Containers needing attention</div><div class="stat-value">{{ stats.issues }}</div><div class="stat-detail">{{ 'Review the issues below' if stats.issues else 'All managed containers healthy' }}</div></article><article class="card stat"><div class="stat-label">Backup status</div><div class="stat-value">{{ stats.backup_label }}</div><div class="stat-detail">{{ stats.backup_detail }}</div></article><article class="card stat"><div class="stat-label">Available images</div><div class="stat-value">{{ stats.images }}</div><div class="stat-detail">Allowed local GLPI and database images</div></article></section>
<div class="grid two-col"><section class="card"><div class="card-head"><div><h2>Environment health</h2><p>Projects with operational issues are shown first.</p></div><a href="{{ url_for('projects_page') }}">View all</a></div>{% if projects %}<div class="table-wrap"><table><thead><tr><th>Project</th><th>Runtime</th><th>Port</th><th></th></tr></thead><tbody>{% for p in projects %}<tr><td><strong>{{ p.name }}</strong><small>{{ p.glpi_image or 'Image not configured' }}</small></td><td><span data-project-status="{{ p.name }}" class="status {{ 'ready' if p.glpi_status=='running' and p.db_status=='running' else 'warning' }}">{{ p.glpi_status }} / {{ p.db_status }}</span></td><td><code>{{ p.active_port or '—' }}</code></td><td><a href="{{ url_for('project_detail_page',project=p.name) }}">Open →</a></td></tr>{% endfor %}</tbody></table></div>{% else %}<div class="empty"><strong>No managed projects yet</strong>Create your first GLPI environment to begin.</div>{% endif %}</section>
<aside class="stack"><section class="card"><div class="card-head"><div><h2>Needs attention</h2><p>Prioritized operational findings.</p></div></div>{% if issues %}<ul class="issue-list">{% for issue in issues %}<li><div class="issue-title">{{ issue.title }}</div><div class="issue-detail">{{ issue.detail }}</div></li>{% endfor %}</ul>{% else %}<div class="empty"><strong>Everything looks healthy</strong>No current operational findings.</div>{% endif %}</section><section class="card"><div class="card-head"><div><h2>Quick actions</h2></div></div><div class="stack"><a class="button" href="{{ url_for('new_project_page') }}">Create or restore a project</a><a class="button secondary" href="{{ url_for('backups_page') }}">Inspect backup readiness</a><a class="button secondary" href="{{ url_for('settings_page') }}">Review security settings</a></div></section></aside></div>
{% if unmanaged_projects %}<section class="card" style="margin-top:20px"><div class="card-head"><div><h2>Detected but not managed</h2><p>Display-only environments that do not meet the Builder management contract.</p></div></div><div class="table-wrap"><table><thead><tr><th>Project</th><th>Status</th><th>Image</th><th>Reason</th></tr></thead><tbody>{% for p in unmanaged_projects %}<tr><td><strong>{{ p.name }}</strong><small>{{ p.path }}</small></td><td>{{ p.glpi_status }} / {{ p.db_status }}</td><td>{{ p.glpi_image }}</td><td>{{ p.issues|join(', ') }}</td></tr>{% endfor %}</tbody></table></div></section>{% endif %}"""

PROJECTS = r"""
<div class="page-head"><div><h1>Projects</h1><p>All Builder-managed and detected GLPI environments.</p></div><a class="button" href="{{ url_for('new_project_page') }}">New project</a></div>
{% if projects %}<section class="grid project-grid">{% for p in projects %}<article class="card project-card"><div class="project-title"><div><h3>{{ p.name }}</h3><div class="status-row">{% if p.simulated %}<span class="status">Simulated</span>{% endif %}<span data-project-status="{{ p.name }}" class="status {{ 'ready' if p.glpi_status=='running' and p.db_status=='running' else 'warning' }}">{{ p.glpi_status }} / {{ p.db_status }}</span>{% if p.backup_source %}<span class="status ready">Backup source</span>{% endif %}<span class="status {{ 'ready' if p.contract_status=='Current' else 'warning' }}">Config {{ p.contract_status }}</span></div></div></div><div class="meta-grid"><div class="meta-item"><span>Web port</span><strong>{{ p.active_port or 'Not configured' }}</strong></div><div class="meta-item"><span>Last rebuild</span><strong>{{ p.last_rebuild or 'Not recorded' }}</strong></div><div class="meta-item"><span>GLPI image</span><strong>{{ p.glpi_image or '—' }}</strong></div><div class="meta-item"><span>Database image</span><strong>{{ p.mariadb_image or '—' }}</strong></div></div><div class="card-actions"><a class="button small" href="{{ url_for('project_detail_page',project=p.name) }}">Manage project</a>{% if p.active_port and not p.simulated %}<a class="button secondary small" href="http://{{ request.host.split(':')[0] }}:{{ p.active_port }}" target="_blank" rel="noopener">Open GLPI ↗</a>{% endif %}</div></article>{% endfor %}</section>{% else %}<section class="card empty"><strong>No managed projects found</strong>Use the guided wizard to create or restore one.</section>{% endif %}
{% if unmanaged_projects %}<section class="card" style="margin-top:20px"><div class="card-head"><div><h2>Detected unmanaged environments</h2><p>Display-only. Builder will not mutate these projects.</p></div><span class="status warning">{{ unmanaged_projects|length }} detected</span></div><div class="table-wrap"><table><thead><tr><th>Project</th><th>Status</th><th>Image</th><th>Reason</th></tr></thead><tbody>{% for p in unmanaged_projects %}<tr><td><strong>{{ p.name }}</strong><small>{{ p.path }}</small></td><td>{{ p.glpi_status }} / {{ p.db_status }}</td><td>{{ p.glpi_image }}</td><td>{{ p.issues|join(', ') }}</td></tr>{% endfor %}</tbody></table></div></section>{% endif %}"""

PROJECT_DETAIL = r"""
<div class="page-head"><div><div class="crumb"><a href="{{ url_for('projects_page') }}">Projects</a> / {{ project.name }}</div><h1>{{ project.name }}</h1><p>Operational status, configuration and recovery controls.</p></div><div class="status-row"><span data-project-status="{{ project.name }}" class="status {{ 'ready' if project.glpi_status=='running' and project.db_status=='running' else 'warning' }}">{{ project.glpi_status }} / {{ project.db_status }}</span><span class="status {{ 'ready' if project.contract_status=='Current' else 'warning' }}">Config {{ project.contract_status }}</span></div></div>
{% if project.simulated %}<div class="notice warning"><strong>Simulated test project.</strong>&nbsp; Docker and host storage are untouched.</div>{% endif %}
<div class="grid detail-layout {{ 'simulated-project' if project.simulated }}"><div class="stack">
<section class="card"><div class="card-head"><div><h2>Current state</h2><p>The most important runtime and compatibility information.</p></div>{% if project.active_port and not project.simulated %}<a class="button small" href="http://{{ request.host.split(':')[0] }}:{{ project.active_port }}" target="_blank" rel="noopener">Open GLPI ↗</a>{% endif %}</div><dl class="definition"><dt>Web port</dt><dd>{{ project.active_port or 'Not configured' }}</dd><dt>GLPI image</dt><dd>{{ project.glpi_image or '—' }}{% if project.newer_glpi_image %}<span class="status warning">Newer local: {{ project.newer_glpi_image }}</span>{% endif %}</dd><dt>Database image</dt><dd>{{ project.mariadb_image or '—' }}{% if project.newer_db_image %}<span class="status warning">Newer local: {{ project.newer_db_image }}</span>{% endif %}</dd><dt>Last rebuild</dt><dd>{{ project.last_rebuild or 'Not recorded' }}</dd><dt>Project path</dt><dd>{{ project.path }}</dd></dl>{% if project.configuration_drift %}<div class="notice warning" style="margin-top:14px"><div><strong>Configuration review recommended</strong><ul class="compat-list">{% for item in project.configuration_drift %}<li>{{ item }}</li>{% endfor %}</ul></div></div>{% endif %}</section>
<section class="card"><div class="card-head"><div><h2>Configuration</h2><p>Normal changes preserve the database and GLPI files.</p></div><a href="{{ url_for('project_compose_page',project=project.name) }}">Generated YAML</a></div><form method="post" action="{{ url_for('change_port_route') }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="project" value="{{ project.name }}"><label for="host_port">Web port</label><input id="host_port" type="number" name="host_port" min="1" max="65535" value="{{ project.active_port }}" required><div class="form-actions"><button type="submit">Apply port</button></div></form><details><summary>SSO and cookie settings</summary><form method="post" action="{{ url_for('change_cookie_route') }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="project" value="{{ project.name }}"><div class="field-row"><div><label>SameSite</label><select name="cookie_samesite"><option {{ 'selected' if project.cookie_samesite=='Lax' }}>Lax</option><option {{ 'selected' if project.cookie_samesite=='Strict' }}>Strict</option><option {{ 'selected' if project.cookie_samesite=='None' }}>None</option></select></div><div><label>Secure</label><select name="cookie_secure"><option {{ 'selected' if project.cookie_secure=='Off' }}>Off</option><option {{ 'selected' if project.cookie_secure=='On' }}>On</option></select></div></div><p class="help">Enable Secure only when GLPI is always accessed through HTTPS.</p><div class="form-actions"><button type="submit">Apply cookie settings</button></div></form></details></section>
<section class="card"><div class="card-head"><div><h2>Diagnostics</h2><p>Read-only checks that help isolate operational issues.</p></div></div><div class="form-actions"><form method="post" action="{{ url_for('diagnose') }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="project" value="{{ project.name }}"><button class="secondary">Run diagnostics</button></form><form method="post" action="{{ url_for('testdb_route') }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="project" value="{{ project.name }}"><button class="secondary">Test database login</button></form></div></section>
<section class="card advanced-zone"><div class="card-head"><div><h2>Advanced recovery</h2><p>These actions interrupt service or alter credentials and require typed confirmation.</p></div></div><div class="form-actions"><button type="button" class="confirmation-trigger" data-dialog-open="rebuild-dialog">Recreate GLPI container</button><button type="button" class="danger" data-dialog-open="recovery-dialog">Recover database credentials</button></div></section></div>
<aside class="stack"><section class="card"><div class="card-head"><div><h2>Backup schedule</h2><p>One Synology dispatcher handles every enabled project.</p></div><span class="status {{ 'ready' if project.backup_status.schedule.dispatcher_healthy else 'warning' }}">{{ 'Dispatcher active' if project.backup_status.schedule.dispatcher_healthy else 'Task not detected' }}</span></div><form class="demo-schedule-form" data-schedule-editor method="post" action="{{ url_for('set_backup_source_route') }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="project" value="{{ project.name }}"><label>Scheduled backups</label><select name="schedule_enabled"><option value="yes" {{ 'selected' if project.backup_status.schedule.enabled }}>Enabled</option><option value="no" {{ 'selected' if not project.backup_status.schedule.enabled }}>Disabled</option></select><label>Frequency</label><select name="schedule_kind"><option value="daily" {{ 'selected' if project.backup_status.schedule.kind=='daily' }}>Daily</option><option value="weekly" {{ 'selected' if project.backup_status.schedule.kind=='weekly' }}>Selected weekdays</option><option value="interval" {{ 'selected' if project.backup_status.schedule.kind=='interval' }}>Fixed interval</option></select><div class="field-row"><div data-for-frequency="daily weekly"><label>Start time</label><input type="time" name="schedule_time" value="{{ project.backup_status.schedule.time or '02:00' }}"></div><div><label>Keep backups for</label><select name="retention_days">{% for days in (7,14,30,60,90,180,365) %}<option value="{{ days }}" {{ 'selected' if project.backup_status.schedule.retention_days==days }}>{{ days }} days</option>{% endfor %}</select></div></div><div data-for-frequency="weekly"><label>Run on weekdays</label><input name="schedule_weekdays" value="{{ project.backup_status.schedule.weekdays or '7' }}" pattern="[1-7](,[1-7])*"><p class="help">Use 1 for Monday through 7 for Sunday, separated by commas.</p></div><div data-for-frequency="interval"><label>Run interval</label><select name="interval_hours">{% for hours in (6,12,24,48,72,168) %}<option value="{{ hours }}" {{ 'selected' if project.backup_status.schedule.interval_hours==hours }}>Every {{ hours }} hours</option>{% endfor %}</select></div><div class="form-actions"><button type="submit">Save schedule</button></div></form><dl class="definition"><dt>Next run</dt><dd>{{ project.backup_status.schedule.next_run or 'Not scheduled' }}</dd><dt>Last attempt</dt><dd>{{ project.backup_status.schedule.last_status }}{% if project.backup_status.schedule.last_attempt %} · {{ project.backup_status.schedule.last_attempt }}{% endif %}</dd><dt>Last success</dt><dd>{{ project.backup_status.schedule.last_success or 'No successful run recorded' }}</dd></dl>{% if project.backup_status.ready %}{% if project.backup_status.latest %}<p><strong>{{ project.backup_status.latest.name }}</strong></p><div class="backup-meta"><span class="status {{ 'warning' if project.backup_age.stale else 'ready' }}">{{ project.backup_age.label }}</span><span class="status">{{ project.backup_status.latest.size_label }}</span></div>{% endif %}<form method="post" action="{{ url_for('run_backup_now_route') }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="project" value="{{ project.name }}"><button>Run backup now</button></form>{% elif project.backup_source %}<ul class="issue-list">{% for issue in project.backup_status.issues %}<li>{{ issue }}</li>{% endfor %}</ul>{% endif %}<div class="form-actions"><a class="button secondary small" href="{{ url_for('backups_page',verify=1) }}">Verify backup sources</a></div></section>
<section class="card"><div class="card-head"><div><h2>Recent activity</h2></div><a href="{{ url_for('activity_page',project=project.name) }}">View all</a></div>{% if project.logs %}<ul class="activity-list">{% for log in project.logs %}<li>{% if project.simulated %}{{ log }} <span class="status">Simulated</span>{% else %}<a href="{{ url_for('view_log',project=project.name,filename=log) }}">{{ log }}</a>{% endif %}</li>{% endfor %}</ul>{% else %}<div class="empty">No action logs yet.</div>{% endif %}</section></aside></div>
<dialog id="rebuild-dialog"><div class="dialog-body"><h2>Recreate GLPI container?</h2><p>The GLPI web container will be briefly unavailable. Database and persistent files remain intact.</p><form method="post" action="{{ url_for('rebuild_glpi_route') }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="project" value="{{ project.name }}"><label>Type <strong>{{ project.name }}</strong> to confirm</label><input name="confirm_rebuild" autocomplete="off" required><div class="dialog-actions"><button type="button" class="secondary" data-dialog-close>Cancel</button><button type="submit" class="danger">Recreate container</button></div></form></div></dialog>
<dialog id="recovery-dialog"><div class="dialog-body"><h2>Recover database credentials?</h2><p>This resets the database user password to the value stored in the project environment.</p><form method="post" action="{{ url_for('resetdb_route') }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="project" value="{{ project.name }}"><label class="check"><input type="checkbox" name="confirm_resetdb" value="yes" required>I understand this changes database credentials.</label><label>Type <strong>{{ project.name }}</strong> to confirm</label><input name="confirm_project" autocomplete="off" required><div class="dialog-actions"><button type="button" class="secondary" data-dialog-close>Cancel</button><button type="submit" class="danger">Recover credentials</button></div></form></div></dialog>"""

COMPOSE_VIEW = r"""
<div class="page-head"><div><div class="crumb"><a href="{{ url_for('projects_page') }}">Projects</a> / <a href="{{ url_for('project_detail_page',project=project) }}">{{ project }}</a> / YAML</div><h1>Generated YAML</h1><p>The effective Docker Compose definition stored for this managed project.</p></div><div class="head-actions"><a class="button secondary" href="{{ url_for('project_detail_page',project=project) }}">Back to project</a><a class="button" href="{{ url_for('project_compose_page',project=project,download=1) }}">Download sanitized YAML</a></div></div>
<section class="card"><div class="code-toolbar"><div><strong>docker-compose.yml</strong><div class="code-note">Environment placeholders are retained. Any literal password, token, secret or embedded URL credential is redacted.</div></div><span class="status ready">Read-only</span></div><pre class="code-view" tabindex="0">{{ compose_yaml }}</pre></section>"""

WIZARD = r"""
<div class="page-head"><div><h1>New project or restore</h1><p>A guided, review-first workflow using the Builder's existing safety checks.</p></div><a class="button secondary" href="{{ url_for('projects_page') }}">Cancel</a></div>
{% if demo_mode %}<div class="notice warning"><strong>Demo sandbox.</strong>&nbsp; Completing this wizard creates only a temporary simulated project in this browser session.</div>{% endif %}
<div class="grid wizard"><section class="card"><div class="steps" aria-label="Workflow steps"><div class="step-marker active"><span class="step-number">1</span>Configure</div><div class="step-marker"><span class="step-number">2</span>Review</div><div class="step-marker"><span class="step-number">3</span>Execute</div></div>
<form method="post" action="{{ url_for('create') }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="backup_root" value="{{ backup_root }}"><input type="hidden" name="container_port" value="8080">
<div class="card-head"><div><h2>1. Choose the operation</h2><p>Restore is recommended when migrating an existing GLPI installation.</p></div></div><div class="mode-grid"><label class="mode"><input type="radio" name="operation_mode" value="restore" checked><span><strong>Full restore</strong><span>Restore database, configuration and GLPI files.</span></span></label><label class="mode"><input type="radio" name="operation_mode" value="fresh"><span><strong>Fresh installation</strong><span>Create an empty GLPI environment from local images.</span></span></label></div>
<div class="restore-fields"><div class="field-row"><div><label>Database backup</label><select name="db_backup_select"><option value="">Select a required database backup</option>{% for value,label in db_backups %}<option value="{{ value }}">{{ label }}</option>{% endfor %}</select></div><div><label>GLPI files and configuration</label><select name="file_backup_select"><option value="">Select required GLPI files</option>{% for value,label in file_backups %}<option value="{{ value }}">{{ label }}</option>{% endfor %}</select></div></div><input type="hidden" name="db_backup_manual"><input type="hidden" name="file_backup_manual"><label class="check"><input type="checkbox" name="skip_plugins" value="yes">Restore without plugins</label></div>
<hr style="border:0;border-top:1px solid #edf1f5;margin:24px 0"><div class="card-head"><div><h2>2. Project identity and versions</h2><p>Only allowed images already present on this Docker host are selectable.</p></div></div><div class="field-row"><div><label>Project name</label><input name="project" pattern="[a-z0-9][a-z0-9_\-]{2,50}" placeholder="glpi-production" required></div><div><label>Web port</label><input type="number" name="host_port" min="1" max="65535" value="{{ suggested_host_port }}" required></div></div><div class="field-row"><div><label>GLPI image</label><select name="glpi_image" required>{% for image in glpi_images %}<option>{{ image }}</option>{% else %}<option value="">No allowed local GLPI image</option>{% endfor %}</select></div><div><label>Database image</label><select name="mariadb_image" required>{% for image in db_images %}<option>{{ image }}</option>{% else %}<option value="">No allowed local database image</option>{% endfor %}</select></div></div>
<details><summary>Advanced settings</summary><div class="field-row"><div><label>Time zone</label><input name="tz" value="{{ tz_default }}"></div><div><label>Use for scheduled backups</label><select name="update_backup_source"><option value="">No</option><option value="yes">Yes</option></select></div></div><div class="field-row"><div><label>Cookie SameSite</label><select name="cookie_samesite"><option>Lax</option><option>Strict</option><option>None</option></select></div><div><label>Cookie Secure</label><select name="cookie_secure"><option>Off</option><option>On</option></select></div></div><button type="button" class="confirmation-trigger" data-dialog-open="overwrite-dialog">Configure existing-project overwrite</button></details>
<div class="form-actions"><button type="submit">Review execution plan →</button></div><dialog id="overwrite-dialog"><div class="dialog-body"><h2>Allow an existing project to be overwritten?</h2><p>This is only needed when deliberately replacing a managed project with the same name.</p><label class="check"><input type="checkbox" name="confirm_destructive" value="yes">Allow overwrite of an existing managed project.</label><label>Type the project name to confirm</label><input name="confirm_project" autocomplete="off"><div class="dialog-actions"><button type="button" class="secondary" data-dialog-close>Cancel</button><button type="button" data-dialog-close>Use confirmation</button></div></div></dialog></form></section>
<aside class="card wizard-summary"><div class="card-head"><div><h2>Safety summary</h2><p>No changes occur until you review and confirm the execution plan.</p></div></div><div class="summary-row"><span>Authentication</span><strong>Required</strong></div><div class="summary-row"><span>CSRF protection</span><strong>Enabled</strong></div><div class="summary-row"><span>Concurrent mutations</span><strong>Blocked</strong></div><div class="summary-row"><span>Backup path policy</span><strong>{{ backup_root }}</strong></div><div class="summary-row"><span>Images</span><strong>Local allowlist only</strong></div><div class="notice warning" style="margin-top:16px;margin-bottom:0">Existing data is only replaced after explicit project-name confirmation.</div></aside></div>"""

BACKUPS = r"""
<div class="page-head"><div><h1>Backups</h1><p>Backup freshness, completeness and available restore sources.</p></div><div class="head-actions"><a class="button secondary" href="{{ url_for('backups_page',verify=1) }}">Verify sources now</a><a class="button" href="{{ url_for('new_project_page') }}">Start restore</a></div></div>
{% if verified_at %}<div class="notice ok"><strong>Verification completed.</strong>&nbsp; Sources were rescanned at {{ verified_at }}.</div>{% endif %}
<section class="card" style="margin-bottom:20px"><div class="card-head"><div><h2>Synology backup dispatcher</h2><p>One NAS task checks all project schedules and runs due backups one at a time.</p></div><span class="status {{ 'ready' if dispatcher_healthy else 'warning' }}">{{ 'Active' if dispatcher_healthy else 'Task not detected' }}</span></div>{% if not dispatcher_healthy %}<div class="notice warning"><div><strong>{{ 'Replace the existing backup task' if legacy_backup_config else 'One-time setup required in DSM' }}</strong><p>{{ 'Edit the existing user-defined task' if legacy_backup_config else 'Create a user-defined task' }} in Control Panel → Task Scheduler, run it every 5 minutes as root, and use this command:</p><pre class="code-view" style="max-height:none">{{ dispatcher_command }}</pre><p>The status changes to Active after its first check-in. You never need a separate DSM task per project.{% if legacy_backup_config %} The old single-project configuration remains available until this change is complete.{% endif %}</p></div></div>{% else %}<p class="help">The dispatcher checked in recently. Frequency, start time and retention remain configurable per project.</p>{% endif %}</section>
<div class="grid two-col"><section class="card"><div class="card-head"><div><h2>Project schedules</h2><p>Backups older than {{ stale_days }} days are marked stale.</p></div></div>{% if projects %}<div class="table-wrap"><table><thead><tr><th>Project</th><th>Schedule</th><th>Next run</th><th>Last result</th><th></th></tr></thead><tbody>{% for p in projects %}<tr><td><strong>{{ p.name }}</strong><small>{{ 'Enabled' if p.backup_status.schedule.enabled else 'Disabled' }}</small></td><td>{% if p.backup_status.schedule.enabled %}<span class="status ready">{{ p.backup_status.schedule.kind|capitalize }}</span><small>{% if p.backup_status.schedule.kind=='interval' %}Every {{ p.backup_status.schedule.interval_hours }} hours{% elif p.backup_status.schedule.kind=='weekly' %}Days {{ p.backup_status.schedule.weekdays }} at {{ p.backup_status.schedule.time }}{% else %}At {{ p.backup_status.schedule.time }}{% endif %}</small>{% else %}<span class="status">Inactive</span>{% endif %}</td><td>{{ p.backup_status.schedule.next_run or '—' }}</td><td><span class="status {{ 'ready' if p.backup_status.schedule.last_status=='success' else ('warning' if p.backup_status.schedule.last_status not in ('Not run','') else '') }}">{{ p.backup_status.schedule.last_status }}</span><small>{{ p.backup_status.schedule.last_attempt }}</small></td><td><a href="{{ url_for('project_detail_page',project=p.name) }}">Manage</a></td></tr>{% endfor %}</tbody></table></div>{% else %}<div class="empty">No projects available.</div>{% endif %}</section>
<aside class="stack"><section class="card"><div class="card-head"><div><h2>Restore inventory</h2><p>Sources below the configured backup root.</p></div></div><dl class="definition"><dt>Backup root</dt><dd>{{ backup_root }}</dd><dt>Database sources</dt><dd>{{ db_backups|length }}</dd><dt>File sources</dt><dd>{{ file_backups|length }}</dd><dt>Complete pairs</dt><dd>{{ complete_pairs }}</dd></dl></section><section class="card"><div class="card-head"><div><h2>Retention</h2><p>Configured per project.</p></div></div><p class="help">The project schedule controls how long its local backup sets remain available. Keep a separate verified off-device copy through Hyper Backup or Snapshot Replication.</p></section></aside></div>
<section class="card" style="margin-top:20px"><div class="card-head"><div><h2>Available restore sources</h2><p>Pairing is inferred conservatively from matching filenames. The restore review validates the selected files again.</p></div><span class="status">Read-only</span></div><div class="table-wrap"><table><thead><tr><th>Type</th><th>Source</th><th>Modified</th><th>Size</th><th>Pairing</th></tr></thead><tbody>{% for item in inventory %}<tr><td><span class="status">{{ item.kind }}</span></td><td><strong>{{ item.label }}</strong><small>{{ item.value }}</small></td><td>{{ item.modified }}</td><td>{{ item.size_label }}</td><td><span class="status {{ 'ready' if item.complete_pair else 'warning' }}">{{ 'Complete pair' if item.complete_pair else 'Unpaired' }}</span></td></tr>{% endfor %}{% if not inventory %}<tr><td colspan="5"><div class="empty">No valid restore sources found below the backup root.</div></td></tr>{% endif %}</tbody></table></div></section>"""

ACTIVITY = r"""
<div class="page-head"><div><h1>Activity</h1><p>Recent Builder action logs across managed projects.</p></div></div>
<section class="card"><div class="card-head"><div><h2>Audit trail</h2><p>Logs are immutable from this interface and never expose authentication secrets.</p></div>{% if selected_project %}<span class="status">{{ selected_project }}</span>{% endif %}</div>{% if activities %}<ul class="activity-list">{% for item in activities %}<li class="activity-row"><div class="audit-icon">↗</div><div><div class="activity-name">{% if item.simulated %}{{ item.label }}{% else %}<a href="{{ url_for('view_log',project=item.project,filename=item.filename) }}">{{ item.label }}</a>{% endif %}</div><div class="activity-meta">{{ item.project }} · {{ 'Simulated activity' if item.simulated else 'Action log' }}</div></div><div class="activity-time">{{ item.time }}</div></li>{% endfor %}</ul>{% else %}<div class="empty"><strong>No activity recorded</strong>Action logs will appear after project operations.</div>{% endif %}</section>"""

SETTINGS = r"""
<div class="page-head"><div><h1>Settings</h1><p>Effective runtime values and enforced deployment guardrails.</p></div></div>
{% if not request.is_secure %}<div class="security-banner"><div>⚠</div><div><strong>Builder is being accessed over HTTP</strong><p>This is acceptable on a trusted management network. Use a reverse proxy with HTTPS before exposing it beyond that network.</p></div></div>{% endif %}
<div class="grid settings-grid" style="margin-top:16px"><section class="card"><div class="card-head"><div><h2>Account security</h2><p>Current administrator protection.</p></div><span class="status ready">Protected</span></div><dl class="definition"><dt>Administrator</dt><dd>{{ auth.username }}</dd><dt>Password storage</dt><dd>PBKDF2-SHA256, 600,000 iterations</dd><dt>Two-factor authentication</dt><dd>Required · TOTP</dd><dt>Idle timeout</dt><dd>{{ auth.idle_minutes }} minutes</dd><dt>Absolute timeout</dt><dd>{{ auth.absolute_hours }} hours</dd></dl><p class="help">Credential rotation remains an offline administrative operation in this release to avoid introducing a recovery bypass.</p></section>
<section class="card"><div class="card-head"><div><h2>Runtime</h2><p>Read-only effective configuration.</p></div></div><dl class="definition"><dt>Builder version</dt><dd>{{ app_version }}</dd><dt>Base path</dt><dd>{{ base_path }}</dd><dt>Backup root</dt><dd>{{ backup_root }}</dd><dt>Managed backup data</dt><dd>{{ backup_data_root }}</dd><dt>Time zone default</dt><dd>{{ tz_default }}</dd><dt>Secure session cookie</dt><dd>{{ 'Enabled' if cookie_secure else 'Disabled' }}</dd></dl></section>
<section class="card"><div class="card-head"><div><h2>Deployment defaults</h2><p>Effective values applied by the Builder.</p></div><span class="status">Read-only</span></div><dl class="definition"><dt>Maximum request URL</dt><dd>{{ request_line_limit }} bytes · {{ request_line_kib }} KiB</dd><dt>GLPI internal port</dt><dd>{{ glpi_internal_port }}</dd><dt>Default SameSite</dt><dd>{{ default_cookie_samesite }}</dd><dt>Default Secure cookie</dt><dd>{{ default_cookie_secure }}</dd><dt>Restore scan limit</dt><dd>{{ max_scan_entries }} results per type</dd><dt>Operation modes</dt><dd>{{ operation_modes|join(', ') }}</dd></dl></section>
<section class="card"><div class="card-head"><div><h2>Security policy</h2><p>Guardrails enforced by every deployment and operation.</p></div></div><div class="policy-list"><div class="policy-item"><strong>Local images only</strong><span>{{ glpi_prefixes|join(', ') }} · {{ db_prefixes|join(', ') }}</span></div><div class="policy-item"><strong>One mutation at a time</strong><span>Concurrent changes are rejected.</span></div><div class="policy-item"><strong>Secrets stay hidden</strong><span>YAML downloads and diagnostics redact credentials.</span></div><div class="policy-item"><strong>2FA required</strong><span>Every administrator session uses TOTP.</span></div><div class="policy-item"><strong>Typed confirmation</strong><span>Recovery and destructive actions require the project name.</span></div><div class="policy-item"><strong>No automatic deletion</strong><span>Backup retention remains under NAS control.</span></div></div></section>
<section class="card"><div class="card-head"><div><h2>Operational guidance</h2></div></div><ul class="issue-list"><li><div class="issue-title">Keep the config directory persistent</div><div class="issue-detail">It contains the administrator hash, TOTP secret and session signing key.</div></li><li><div class="issue-title">Restrict port 5055</div><div class="issue-detail">Allow only trusted management devices or a management VLAN.</div></li><li><div class="issue-title">Verify backups regularly</div><div class="issue-detail">Use Backups → Verify sources and test restores periodically.</div></li></ul></section></div>"""


def page_template(content):
    return APP_SHELL.replace("__PAGE_CONTENT__", content)
